      return (function pump() {
        return reader.read().then(function (r) {
          if (r.done) return new Blob(chunks, { type: type });
          chunks.push(r.value); recv += r.value.length;
          if (pct) pct.textContent = Math.min(100, Math.round(recv / total * 100)) + "%";
